/* Design tokens for Tidepool design system */

:root {
  /* Colors - Text */
  --text-primary: #1b2433;

  /* Colors - Surface */
  --surface-page: #ffffff;

  /* Colors - Components */
  --button-background: #1f5fd6;
  --button-text: #ffffff;
  --chip-background: #e8eef9;
  --chip-text: #1b2433;
  --field-border: #7d8799;

  /* Spacing */
  --padding-xs: 4px;
  --padding-s: 8px;
  --padding-m: 12px;
  --gap-s: 4px;

  /* Border Radius */
  --radii-chip: 16px;
  --radii-button: 8px;
  --radii-field: 6px;

  /* Stroke */
  --stroke-default: 1px;
}

@media (prefers-color-scheme: dark) {
  :root {
    /* Colors - Text */
    --text-primary: #f0f0f0;

    /* Colors - Surface */
    --surface-page: #1a1a1a;

    /* Colors - Components */
