    --padding-s: 8px;
    --padding-m: 12px;
    --gap-s: 4px;

    /* Border Radius - unchanged in dark mode */
    --radii-chip: 16px;
    --radii-button: 8px;
    --radii-field: 6px;

    /* Stroke - unchanged in dark mode */
    --stroke-default: 1px;
  }
}

