import './Button.css';

export function Button({
  disabled = false,
  label = 'Save',
  state = 'Default',
  className,
  ...props
}) {
  const baseClass = 'button';
  const stateClass = state === 'Hover' && !disabled ? 'button--hover' : '';
  const disabledClass = disabled ? 'button--disabled' : '';

  const classes = [baseClass, stateClass, disabledClass, className]
    .filter(Boolean)
    .join(' ');

  return (
    <button
      className={classes}
      disabled={disabled}
      {...props}
    >
      {label}
    </button>
  );
}

