import './Chip.css';

export default function Chip({ className, icon = false, label = 'Filter', size = 'M' }) {
  const isLAndIcon = size === 'L' && icon;
  const chipClass = className || `chip chip--${size.toLowerCase()}${icon ? ' chip--icon' : ''}`;

  return (
    <div className={chipClass}>
      {!icon && (
        <p className="chip__label">{label}</p>
      )}
      {isLAndIcon && (
        <>
          <svg
            className="chip__icon"
            viewBox="0 0 12 12"
            width="12"
            height="12"
            aria-hidden="true"
          >
            <circle cx="6" cy="6" r="6" fill="currentColor" />
          </svg>
          <p className="chip__label">{label}</p>
        </>
      )}
    </div>
  );
}

