.tag {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 20px;
  padding: var(--padding-xs, 4px) var(--padding-s, 8px);
  border-radius: var(--radii-chip, 16px);
  width: fit-content;
  background-color: var(--chip-background, #e8eef9);
  color: var(--chip-text, #1b2433);
}

.tag--neutral {
  background-color: var(--chip-background, #e8eef9);
  color: var(--chip-text, #1b2433);
}

.tag--positive {
  background-color: var(--chip-background-positive, #d6f5e3);
  color: var(--chip-text-positive, #136c3a);
}

.tag__label {
  font-family: Inter, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  font-size: 12px;
  font-weight: 500;
  line-height: 16px;
  margin: 0;
  padding: 0;
  word-break: break-word;
  white-space: nowrap;
  flex-shrink: 0;
}

