import "./Tag.css";

export default function Tag({ className, label = "New", tone = "Neutral" }) {
  const toneClass = tone === "Positive" ? "tag--positive" : "tag--neutral";

  return (
    <div className={`tag ${toneClass} ${className || ""}`}>
      <p className="tag__label">{label}</p>
    </div>
  );
}

